package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
final class RecordCollaborationBrowserAcceptance {
 static void click(Page page,String name){ServiceOutagesBrowserAcceptance.click(page,name);}
 static void run(BrowserTest h)throws Exception{
  String reader="ActivityBrowser"+id().substring(0,8),record;try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.createAccount(db,map("name",reader,"password",WorkflowSupport.PASSWORD,"role","reader"));record=Service.create(db,"incident",map("short_description","Browser collaboration record"),"admin").get("sys_id").toString();db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var authorContext=browser.newContext();var readerContext=browser.newContext()){
   var author=authorContext.newPage();h.login(author,"admin");var page=readerContext.newPage();FulfilmentBrowserAcceptance.login(h,page,reader);page.navigate(h.base()+"/record/incident/"+record);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Follow activity and mention colleagues")).press("Enter");page.getByLabel("Record changes").check();page.getByLabel("Shared comments",new Page.GetByLabelOptions().setExact(true)).check();assertThat(page.getByLabel("Staff work notes",new Page.GetByLabelOptions().setExact(true))).hasCount(0);click(page,"Save activity subscription");assertThat(page.getByLabel("Record changes")).isChecked();ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/record-subscription-light.png")).setFullPage(true));
   author.navigate(h.base()+"/record/incident/"+record+"/collaboration");author.getByLabel("Journal message").fill("Browser shared evidence <script>not executed</script>");author.getByLabel("Mentioned usernames").fill(reader);click(author,"Post journal entry");assertThat(author.locator("[role=status]")).containsText("Journal entry saved");page.navigate(h.base()+"/account/notifications");assertThat(page.locator("main")).containsText("You were mentioned");assertThat(page.locator("main")).not().containsText("Browser shared evidence");String context=page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Review related work")).getAttribute("href");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Review related work")).press("Enter");assertThat(page.locator("main")).containsText("Browser shared evidence <script>not executed</script>");assertThat(page.locator("main script")).hasCount(0);page.getByLabel("Journal message").fill("Reader follow-up");click(page,"Post journal entry");click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/record-mention-reader-dark.png")).setFullPage(true));author.getByLabel("Entry type").selectOption("note");author.getByLabel("Journal message").fill("STAFF_ONLY_BROWSER_ACTIVITY");author.getByLabel("Mentioned usernames").fill("");click(author,"Post journal entry");page.reload();assertThat(page.locator("main")).not().containsText("STAFF_ONLY_BROWSER_ACTIVITY");
   try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,"incident",record),actor,map("visibility","private","owner_id",actor));db.connection.commit();}assertEquals(404,readerContext.request().get(h.base()+context).status());page.navigate(h.base()+"/account/notifications");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Manage followed records")).press("Enter");assertThat(page.locator("main")).containsText("Unavailable record");assertThat(page.locator("main")).not().containsText("Browser collaboration record");click(page,"Stop following this record");assertThat(page.locator("main")).containsText("No followed records");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/record-subscription-removed-dark.png")).setFullPage(true));
  }
 }
}
